@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		var p := (base + "/" + n) if base != "" else n
		if d.current_is_dir():
			if n != "imported" and n != "folding":
				_walk(p, out)
		else:
			out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk(".godot", files)
	var lines: Array = []
	var txt_hits: Array = []
	for f in files:
		var fs := String(f)
		var fa := FileAccess.open("res://" + fs, FileAccess.READ)
		if fa == null:
			continue
		var size := fa.get_length()
		fa.close()
		lines.append(fs + " | " + str(size) + "B")
		if size < 8000000:
			var txt: String = FileAccess.get_file_as_string("res://" + fs)
			if txt.find("textures/T_Imp") != -1 or txt.find("textures/T_Hair") != -1 or txt.find("textures/T_Puglin") != -1:
				txt_hits.append(fs)
	var uid_files := [
		"addons/fightengine/assets/icons/at-icons/2d/box.svg.uid",
		"addons/fightengine/assets/icons/at-icons/3d/box.svg.uid",
		"addons/fightengine/assets/icons/at-icons/2d/box_wireframe.svg.uid",
		"addons/fightengine/assets/icons/at-icons/3d/box_wireframe.svg.uid"
	]
	var uid_vals := {}
	for uf in uid_files:
		if FileAccess.file_exists("res://" + String(uf)):
			uid_vals[String(uf)] = FileAccess.get_file_as_string("res://" + String(uf)).strip_edges()
		else:
			uid_vals[String(uf)] = "NO .uid FILE"
	var rep := {"godot_files": lines, "stale_record_hits": txt_hits, "uid_values": uid_vals}
	var out := FileAccess.open("res://tools/gc_warn_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "WARN files=" + str(lines.size()) + " stale_hits=" + str(txt_hits.size()) + " uids=" + str(uid_vals)
